parent = {}
children = {}
for _ in range(n - 1):
    child, ancestor = input().split()
    parent[child] = ancestor
    children.setdefault(ancestor, []).append(child)
    children.setdefault(child, [])
q = int(input())
queries = [input().split() for _ in range(q)]
for a, b in queries:
    children.setdefault(a, [])
    children.setdefault(b, [])

enter, leave = {}, {}
if children:
    root = next(name for name in children if name not in parent)
    stack = [(root, False)]
    clock = 0
    while stack:
        name, exiting = stack.pop()
        if exiting:
            leave[name] = clock
        else:
            enter[name] = clock
            clock += 1
            stack.append((name, True))
            for child in children[name]:
                stack.append((child, False))
def ancestor(a, b):
    return a != b and enter[a] <= enter[b] < leave[a]
for a, b in queries:
    print(1 if ancestor(a, b) else 2 if ancestor(b, a) else 0)

